+    let mut attempts = tick::Attempts::default();
+    let result = tick::tick(&h.c, &q_venue(&h, &server.uri()), bot.id, &FixedClock(h.app.now()), &mut attempts).await.unwrap();
+    let current = model::load_bot(&h.c, bot.id).unwrap();
